function Obj($x,$rank,$side) { $shown=$x[0]; if($shown -match '^ONY'){$shown='ONYEKA'}; [ordered]@{full_name=$null;displayed_name=$shown;position=$null;injury_status=$null;player_id=$null;player_url=$null;formation_row=[int]$x[1];slot_index=[int]$x[2];starting_probability_rank=$rank} }
$all=@(); $primary=0; $total=0
foreach($f in $fixtures){ $m=[ordered]@{match_time=$f[0]}; foreach($side in @('home','away')) { $name=if($side -eq 'home'){$f[1]}else{$f[2]}; $arr=@(); foreach($x in $teams[$name]) { $arr += Obj $x 1 $side; $primary++; $total++; $rank=2; foreach($a in $x[3]) { foreach($part in ($a -split '/')) { $arr += Obj @($part.Trim(),$x[1],$x[2]) $rank $side; $rank++; $total++ } } }; $m[$side]=[ordered]@{team_name=$name;side=$side;lineup_status='Predicted Lineup';players=$arr} }; $all += $m }
